"""
Coarse scene splitting for long media (WhisperJAV-inspired).

Uses **fixed-length windows** (default ≤7 min). Silence scanning via ffmpeg was
removed as the default: on long films it re-decodes the whole file and often
took longer than WhisperSeg itself. WhisperSeg already runs 30s ONNX chunks.
"""

from __future__ import annotations

from typing import Any, Callable

ProgressCb = Callable[[dict[str, Any]], None]

# Split when media is longer than this (seconds)
SCENE_SPLIT_MIN_S = 600.0
# Max scene length (~7 min, WhisperJAV Silero-scene style)
MAX_SCENE_S = 420.0


def _enforce_max_scene(
    chapters: list[dict[str, float]],
    *,
    max_scene_s: float,
) -> list[dict[str, float]]:
    out: list[dict[str, float]] = []
    for ch in chapters:
        start = float(ch["start"])
        end = float(ch["end"])
        if end - start <= max_scene_s:
            out.append({"start": start, "end": end})
            continue
        t = start
        while t < end - 0.25:
            nxt = min(t + max_scene_s, end)
            out.append({"start": t, "end": nxt})
            t = nxt
    return out


def detect_coarse_scenes(
    media_path: str,
    *,
    duration_s: float,
    min_media_s: float = SCENE_SPLIT_MIN_S,
    max_scene_s: float = MAX_SCENE_S,
    on_progress: ProgressCb | None = None,
) -> list[dict[str, float]]:
    """
    Return coarse scenes covering [0, duration_s].

    Short media → single scene. Long media → fixed windows of max_scene_s.
    ``media_path`` is unused (kept for call-site compatibility).
    """
    del media_path  # fixed windows need duration only
    duration_s = max(0.0, float(duration_s or 0.0))
    if duration_s <= 0:
        return [{"start": 0.0, "end": 0.0}]
    if duration_s < min_media_s:
        return [{"start": 0.0, "end": duration_s}]

    scenes = _enforce_max_scene(
        [{"start": 0.0, "end": duration_s}],
        max_scene_s=max_scene_s,
    )

    if on_progress:
        on_progress(
            {
                "stage": "scene",
                "percent": 6,
                "detail": f"{len(scenes)} 个场景 · 单段 ≤{max_scene_s / 60:.0f} 分钟",
            }
        )
    return scenes
